messages.content:
Generate a standalone C reproducer that triggers this vulnerability:

File: contrib/libtests/pngvalid.c
Line: 1861
Function: store_malloc
Bug type: integer-overflow
CWE: CWE-190
Explanation: The allocation size passed to malloc is computed as cb + sizeof(*new) + sizeof(pool->mark) without checking for overflow. If cb is large enough, this addition can wrap, causing a too-small allocation. The subsequent memcpy((png_byte *)(new+1) + cb, pool->mark, sizeof pool->mark) then writes past the end of the allocated block, leading to heap memory corruption.

Source context:
```c
     1821:             ps->current->name : "unknown file") : ps->wname);
     1822:    pool->current = 0;
     1823: 
     1824:    if (pool->limit > pool->max_limit)
     1825:       pool->max_limit = pool->limit;
     1826: 
     1827:    pool->limit = 0;
     1828: 
     1829:    if (pool->total > pool->max_total)
     1830:       pool->max_total = pool->total;
     1831: 
     1832:    pool->total = 0;
     1833: 
     1834:    /* Get a new mark too. */
     1835:    store_pool_mark(pool->mark);
     1836: }
     1837: 
     1838: /* The memory callbacks: */
     1839: static void *
     1840: store_malloc(png_struct *ppIn, png_alloc_size_t cb)
     1841: {
     1842:    const png_struct *pp = ppIn;
     1843:    store_pool *pool = voidcast(store_pool*, png_get_mem_ptr(pp));
     1844:    store_memory *new = voidcast(store_memory*, malloc(cb + (sizeof *new) +
     1845:       (sizeof pool->mark)));
     1846: 
     1847:    if (new != NULL)
     1848:    {
     1849:       if (cb > pool->max)
     1850:          pool->max = cb;
     1851: 
     1852:       pool->current += cb;
     1853: 
     1854:       if (pool->current > pool->limit)
     1855:          pool->limit = pool->current;
     1856: 
     1857:       pool->total += cb;
     1858: 
     1859:       new->size = cb;
     1860:       memcpy(new->mark, pool->mark, sizeof new->mark);
>>>  1861:       memcpy((png_byte *)(new+1) + cb, pool->mark, sizeof pool->mark);
     1862:       new->pool = pool;
     1863:       new->next = pool->list;
     1864:       pool->list = new;
     1865:       ++new;
     1866:    }
     1867: 
     1868:    else
     1869:    {
     1870:       /* NOTE: the PNG user malloc function cannot use the png_ptr it is passed
     1871:        * other than to retrieve the allocation pointer!  libpng calls the
     1872:        * store_malloc callback in two basic cases:
     1873:        *
     1874:        * 1) From png_malloc; png_malloc will do a png_error itself if NULL is
     1875:        *    returned.
     1876:        * 2) From png_struct or png_info structure creation; png_malloc is
     1877:        *    to return so cleanup can be performed.
     1878:        *
     1879:        * To handle this store_malloc can log a message, but can't do anything
     1880:        * else.
     1881:        */
     1882:       store_log(pool->store, pp, "out of memory", 1 /* is_error */);
     1883:    }
     1884: 
     1885:    return new;
     1886: }
